import type { Dayjs } from 'dayjs'

export const getDefaultImg = (): string => {
  const defualtImg = 'data:image/png;base64,'
  return defualtImg
}
// 判断数组项是否有重复
export const hasArrRepeat = (arr: Record<string | number, string | number | boolean>[], key: string | number): boolean => {
  const seen = new Set()
  for (const item of arr) {
    const value = JSON.stringify(item[key])
    if (seen.has(value)) return true
    seen.add(value)
  }
  return false
}

// 判断时间段是否有重叠
export const isTimeRangeOverlap = (start: [Dayjs, Dayjs], end: [Dayjs, Dayjs]): boolean => {
  // 将所有时间点转换为毫秒，便于比较
  const start1Ms = start[0].valueOf()
  const end1Ms = start[1].valueOf()
  const start2Ms = end[0].valueOf()
  const end2Ms = end[1].valueOf()
  // 判断时间段是否有重叠
  return !(end1Ms <= start2Ms || end2Ms <= start1Ms)
}
// 批量判断
export const checkPeriodsOverlap = (periods: [Dayjs, Dayjs][]): boolean => {
  for (let i = 0; i < periods.length; i++) {
    for (let j = i + 1; j < periods.length; j++) {
      if (isTimeRangeOverlap(periods[i], periods[j])) {
        return true
      }
    }
  }
  return false
}
