/** 将时分字符转换为分钟数 */
export const parseTime = (timeStr: string = '00:00'): number => {
  const [hours, minutes] = timeStr.split(':').map(Number)
  return hours * 60 + minutes
}

/** 时间排序 */
export const timeListSort = (times: TimeListState[]): TimeListState[] => {
  return times.sort((a, b) => {
    const startA = a.startTime ? (!a.nextDayBool ? parseTime(a.startTime) : parseTime(a.startTime) + 24 * 60) : 0
    const endA = a.endTime ? (!a.nextDayBool ? parseTime(a.endTime) : parseTime(a.endTime) + 24 * 60) : 0
    const startB = b.startTime ? (!b.nextDayBool ? parseTime(b.startTime) : parseTime(b.startTime) + 24 * 60) : 0
    const endB = b.endTime ? (!b.nextDayBool ? parseTime(b.endTime) : parseTime(b.endTime) + 24 * 60) : 0

    if (startA < startB) return -1
    if (startA > startB) return 1

    if (endA < endB) return -1
    if (endA > endB) return 1

    return 0
  })
}
